function qpEscape($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function qpConsultantName(){return 'Ing. Jhon H. Medrano Martinez';}
function qpManagerName(){return 'Blanca Martinez Bravo';}
function qpConsultantRubric($name){
 if(mb_strtolower(trim(preg_replace('/\s+/u',' ',(string)$name)),'UTF-8')!==mb_strtolower(qpConsultantName(),'UTF-8'))return null;
 foreach([dirname(__DIR__).'/nuevo/static/images/consultor-jhon-rubrica-limpia.png',dirname(__DIR__,2).'/static/images/consultor-jhon-rubrica-limpia.png'] as $path)if(is_file($path)&&filesize($path)<=1000000){$bytes=file_get_contents($path);return ['mime'=>'image/png','base64'=>base64_encode($bytes),'sha256'=>hash('sha256',$bytes)];}
 return null;
}
function qpRubricImage($rubric){
 if(!is_array($rubric)||($rubric['mime']??'')!=='image/png'||!is_string($rubric['base64']??null)||strlen($rubric['base64'])>1340000)return '';
 $bytes=base64_decode($rubric['base64'],true);if($bytes===false||!hash_equals($rubric['sha256']??'',hash('sha256',$bytes)))return '';
 return '<img class="consultant-rubric-image" src="data:image/png;base64,'.$rubric['base64'].'" alt="Rúbrica del consultor">';
}
